import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.BdWD-ld-.js";const u=JSON.parse('{"title":"2026-11-17 Agent 核心研究与竞品动态","description":"44项事实观察与6组研究分析：授权来源、停止结算、协作交付、可解释审计与数字员工应用。","frontmatter":{"title":"2026-11-17 Agent 核心研究与竞品动态","description":"44项事实观察与6组研究分析：授权来源、停止结算、协作交付、可解释审计与数字员工应用。","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-17.md","filePath":"zh/runtime/daily-intelligence/2026-11-17.md","lastUpdated":1794885097000}'),n={name:"zh/runtime/daily-intelligence/2026-11-17.md"};function p(l,a,i,s,h,d){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="_2026-11-17-agent-核心研究与竞品动态" tabindex="-1">2026-11-17 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-17-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-17 Agent 核心研究与竞品动态&quot;">​</a></h1><p>今天最值得深入研究的是三件事：<strong>Agent 消息不能冒充人的授权；Stop/超时返回不能冒充副作用已停止；子任务有输出不能冒充父任务已经收到并验收。</strong> Orca、Codex、OpenHands、Paperclip、ADK 等提供了具体修复或开放反例。AAE 的 A2A 扩展讨论则提供请求绑定与“获准但执行失败/被拒且未执行”的协议对照，仍属开放提案。</p><p>本轮 <strong>44项事实观察 → 6组研究分析</strong>。实际执行起点为 <strong>2026-11-17 10:48:23 Asia/Shanghai（02:48:23 UTC）</strong>；Registry 从最新 main 读取，47位研究者。上次成功记录为 <code>2026-11-16T010724Z</code>；没有伪造11月15日等漏跑日期的日报。当前重点新增窗口接上轮各来源成功基线，历史未完成分页继续保留缺口。事件发生时间以下均用 UTC，发布日期与合入日期分开。</p><p>“已合入”只证明上游主干状态；除明确给出 Release 或官方可用公告外，不代表已打包、部署或默认开启。测试数字均为注明的上游证据，本轮<strong>没有新增本地实验、安装体验、文章或开发评审派工</strong>。CodeFlowMu/FCoP 关联均是研究判断与待验证候选。</p><h2 id="事实观察" tabindex="-1">事实观察 <a class="header-anchor" href="#事实观察" aria-label="Permalink to &quot;事实观察&quot;">​</a></h2><p><span id="o1"></span></p><h3 id="o1-kaptein-研究入口-kyvvu-路径策略更新" tabindex="-1">O1 Kaptein 研究入口：Kyvvu 路径策略更新 <a class="header-anchor" href="#o1-kaptein-研究入口-kyvvu-路径策略更新" aria-label="Permalink to &quot;O1 Kaptein 研究入口：Kyvvu 路径策略更新&quot;">​</a></h3><p>11月16日 13:57 UTC，Kyvvu/manifests 已提交 Claude Code Safety manifest 2.0.0，依赖 kyvvu-engine 1.1.0。策略按 critical 拒绝、high 请求开发者确认、low 放行并记录；读取 secret 后再执行外发动作会触发路径规则。污点只覆盖任务最近 enforcement_history_limit 步，默认10,000步，模型记录也占窗口；并非永久会话污点。Shell 正则仍可被变量、eval 或解释器间接调用绕过，需要文件与网络隔离配合。提交来自 kyvvu-bot，不能据此声称 Kaptein 本人提交或完整平台已开源。</p><p>原始来源：<a href="https://github.com/Kyvvu/manifests/commit/d7062e2de2b42144219f387106d81e44b1aa204f" target="_blank" rel="noreferrer">1</a></p><p><span id="o2"></span></p><h3 id="o2-orca-agent-来信不再冒充人的授权" tabindex="-1">O2 Orca：Agent 来信不再冒充人的授权 <a class="header-anchor" href="#o2-orca-agent-来信不再冒充人的授权" aria-label="Permalink to &quot;O2 Orca：Agent 来信不再冒充人的授权&quot;">​</a></h3><p>11月16日 18:50 UTC，#43093 已合入。其他 Agent 的消息原来作为普通 user 消息进入接收方；上游报告一次真实 Codex 运行据此把风险上传判为“用户明确授权”。修复后只注入取信指针，由工具读取带来源的消息；界面仍展示发送者。被 Codex 自动审查拒绝的动作，由本机 Orca 窗口中的人点击 Approve once。前述复现是上游证据，本轮未本地重放。学习价值高，治理竞争风险上调；雷达仍在第二圈，优先级提高。</p><p>原始来源：<a href="https://github.com/stablyai/orca/pull/43093" target="_blank" rel="noreferrer">1</a></p><p><span id="o3"></span></p><h3 id="o3-orca-仓库-hook-信任扩大到未来版本" tabindex="-1">O3 Orca：仓库 hook 信任扩大到未来版本 <a class="header-anchor" href="#o3-orca-仓库-hook-信任扩大到未来版本" aria-label="Permalink to &quot;O3 Orca：仓库 hook 信任扩大到未来版本&quot;">​</a></h3><p>11月16日 21:50 UTC，#42890 已合入。Always trust 覆盖仓库未来 orca.yaml hook 变更；已有任一按版本批准也被视为仓库信任。Run once 仍绑定展示内容的 hash，自动化需要 Always trust；VM 和跨主机重名仓库等情形继续按版本批准。减少审批次数的同时扩大供应链信任范围，不能把它记为普遍更安全。学习价值高，风险需与 O2 分开评估；雷达新增信任迁移观察。</p><p>原始来源：<a href="https://github.com/stablyai/orca/pull/42890" target="_blank" rel="noreferrer">1</a></p><p><span id="o4"></span></p><h3 id="o4-codex-审查证据有时间截面-嵌套动作保留父调用上下文" tabindex="-1">O4 Codex：审查证据有时间截面，嵌套动作保留父调用上下文 <a class="header-anchor" href="#o4-codex-审查证据有时间截面-嵌套动作保留父调用上下文" aria-label="Permalink to &quot;O4 Codex：审查证据有时间截面，嵌套动作保留父调用上下文&quot;">​</a></h3><p>11月17日 00:59 / 02:32 UTC，两项 PR 已合入。#61929 按源顺序冻结 ReviewCutoff，避免较晚撤权等证据流入较早审查。#61946 以调用 ID 匹配宿主验证的父工具名和参数，但嵌套动作仍是被审对象；歧义或缺失证据省略，不能挤掉截图或常规证据。后者 guardian_nested_approval_context 默认关闭。主干合入不等于所有客户端已发布或开启。</p><p>原始来源：<a href="https://github.com/openai/codex/pull/61929" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/openai/codex/pull/61946" target="_blank" rel="noreferrer">2</a></p><p><span id="o5"></span></p><h3 id="o5-codex-迟到终态不能取消下一轮审批" tabindex="-1">O5 Codex：迟到终态不能取消下一轮审批 <a class="header-anchor" href="#o5-codex-迟到终态不能取消下一轮审批" aria-label="Permalink to &quot;O5 Codex：迟到终态不能取消下一轮审批&quot;">​</a></h3><p>11月16日 12:14 / 16:38 UTC，两项 PR 已合入。#61801 只让最新 started turn 的终态取消当前请求、改变线程状态，防止旧 turn 晚到结束事件误取消新审批。#61841 对原 turn 结束后才出现的后台命令审批，取消时补发 Declined 和 item/completed，保留原 turn ID，并送达替换后的订阅者。重点是审批归属与最终回执，不只是按钮显示。</p><p>原始来源：<a href="https://github.com/openai/codex/pull/61801" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/openai/codex/pull/61841" target="_blank" rel="noreferrer">2</a></p><p><span id="o6"></span></p><h3 id="o6-codex-收信确认、唤醒与中断分别建模" tabindex="-1">O6 Codex：收信确认、唤醒与中断分别建模 <a class="header-anchor" href="#o6-codex-收信确认、唤醒与中断分别建模" aria-label="Permalink to &quot;O6 Codex：收信确认、唤醒与中断分别建模&quot;">​</a></h3><p>11月16日 22:07—23:58 UTC，三项 PR 已合入。send_message 返回 Message accepted，并提醒要让空闲非 root Agent 立即行动需 followup_task。默认关闭的 interrupt_at_item_boundary 可保留当前输出项、立即取消工具，未执行调用写 aborted，等原 turn 终态后再开始 follow-up；压缩期间中断保留摘要和已完成答案。收信不等于开始执行，中断也不等于抹去已产生结果。</p><p>原始来源：<a href="https://github.com/openai/codex/pull/61894" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/openai/codex/pull/61909" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/openai/codex/pull/61916" target="_blank" rel="noreferrer">3</a></p><p><span id="o7"></span></p><h3 id="o7-codex-代理转发中的工具调用归因" tabindex="-1">O7 Codex：代理转发中的工具调用归因 <a class="header-anchor" href="#o7-codex-代理转发中的工具调用归因" aria-label="Permalink to &quot;O7 Codex：代理转发中的工具调用归因&quot;">​</a></h3><p>11月16日 19:14 UTC，#61860 已合入。仅对 CODEX_TOOL_CALL_ATTRIBUTION_PROXY 指定的上游代理附加控制器工具调用 ID，覆盖 HTTP 与 HTTPS CONNECT；清除调用者自带同名头，不向直连目的地或其他代理发送，默认不启用。它提供网络请求到工具调用的关联线索，不自动证明实际副作用或授权成立。</p><p>原始来源：<a href="https://github.com/openai/codex/pull/61860" target="_blank" rel="noreferrer">1</a></p><p><span id="o8"></span></p><h3 id="o8-claude-code-2-1-326-后台身份、审批遥测和并行-mcp-修复" tabindex="-1">O8 Claude Code 2.1.326：后台身份、审批遥测和并行 MCP 修复 <a class="header-anchor" href="#o8-claude-code-2-1-326-后台身份、审批遥测和并行-mcp-修复" aria-label="Permalink to &quot;O8 Claude Code 2.1.326：后台身份、审批遥测和并行 MCP 修复&quot;">​</a></h3><p>11月16日 22:11 UTC，v2.1.326 已发行。发布说明包括：后台网关环境丢失时先停止再发模型请求；避免 PID 复用误终止别人的进程；补齐 managed PreToolUse 拒绝的 tool_decision / permission_denials；修复并行 MCP 大结果同毫秒保存导致读到别的调用结果；远程 Stop 覆盖后台 subagent。均是上游发布说明，未本地逐项复现，也不能推成“治理问题已全部解决”。</p><p>原始来源：<a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.326" target="_blank" rel="noreferrer">1</a></p><p><span id="o9"></span></p><h3 id="o9-agents-python-恢复后的输入与交接历史不重复嵌套" tabindex="-1">O9 Agents Python：恢复后的输入与交接历史不重复嵌套 <a class="header-anchor" href="#o9-agents-python-恢复后的输入与交接历史不重复嵌套" aria-label="Permalink to &quot;O9 Agents Python：恢复后的输入与交接历史不重复嵌套&quot;">​</a></h3><p>11月16日 22:53 至17日 01:20 UTC，两项 PR 已合入。#6042 修复审批暂停后加入消息、请求未获服务端接受即失败，再保存恢复重试时 normalized history 重复消息；#6041 识别 RunState JSON 写出的单文本交接摘要，避免后续 handoff 反复嵌套。它们是输入历史与快照兼容修复，不是外部动作恰好一次执行的证明。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-python/pull/6042" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/openai/openai-agents-python/pull/6041" target="_blank" rel="noreferrer">2</a></p><p><span id="o10"></span></p><h3 id="o10-agents-python-人的批准绑定待决调用-保留已完成检查" tabindex="-1">O10 Agents Python：人的批准绑定待决调用，保留已完成检查 <a class="header-anchor" href="#o10-agents-python-人的批准绑定待决调用-保留已完成检查" aria-label="Permalink to &quot;O10 Agents Python：人的批准绑定待决调用，保留已完成检查&quot;">​</a></h3><p>11月16日 22:52—23:00 UTC，两项 PR 已合入。demo REPL 原来输入 y 会开启新聊天轮次，留下未完成调用；现在展示待决动作并对该调用应用决定后续跑。并行输出 guardrail 触发 tripwire 时，会恰好记录已完成兄弟检查，再取消未完成检查，取消清理期间才产生的结果不冒充正常完成。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-python/pull/6045" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/openai/openai-agents-python/pull/6040" target="_blank" rel="noreferrer">2</a></p><p><span id="o11"></span></p><h3 id="o11-agents-python-失败尝试也进入用量账本" tabindex="-1">O11 Agents Python：失败尝试也进入用量账本 <a class="header-anchor" href="#o11-agents-python-失败尝试也进入用量账本" aria-label="Permalink to &quot;O11 Agents Python：失败尝试也进入用量账本&quot;">​</a></h3><p>11月16日 23:00 UTC，#6046 已合入。Responses 返回 failed 或 incomplete 且带用量时，HTTP / WebSocket 路径在抛错前记录 run usage 与 response span；非流式重试成功或耗尽预算时，每次供应商报告用量只记一次。研究价值是失败成本可见，不等于未返回用量也能精确计费。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-python/pull/6046" target="_blank" rel="noreferrer">1</a></p><p><span id="o12"></span></p><h3 id="o12-agents-js-重放尊重-mcp-结果删改-坏-span-不吞掉整批" tabindex="-1">O12 Agents JS：重放尊重 MCP 结果删改，坏 span 不吞掉整批 <a class="header-anchor" href="#o12-agents-js-重放尊重-mcp-结果删改-坏-span-不吞掉整批" aria-label="Permalink to &quot;O12 Agents JS：重放尊重 MCP 结果删改，坏 span 不吞掉整批&quot;">​</a></h3><p>11月17日 01:02 / 01:03 UTC，两项 PR 已合入。hosted MCP 重放使用当前类型项的 output 覆盖旧 provider metadata，保留空字符串，尊重编辑、脱敏与删除；console tracing 遇到一个无法序列化的 span 时跳过该条、警告计数，继续输出其余 span。主干修复尚不等于新 npm 版本已发布。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-js/pull/2672" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/openai/openai-agents-js/pull/2670" target="_blank" rel="noreferrer">2</a></p><p><span id="o13"></span></p><h3 id="o13-agents-js-审批续跑时保留已终结的兄弟工具结果" tabindex="-1">O13 Agents JS：审批续跑时保留已终结的兄弟工具结果 <a class="header-anchor" href="#o13-agents-js-审批续跑时保留已终结的兄弟工具结果" aria-label="Permalink to &quot;O13 Agents JS：审批续跑时保留已终结的兄弟工具结果&quot;">​</a></h3><p>11月17日创建，#2673 仍 OPEN、非 DRAFT、未合入。拟在一个工具已完成、另一个等待审批时，恢复后按同一模型响应的原始调用顺序应用 toolUseBehavior，避免多发模型调用；仅新完成工具发事件、写 Session，并校验恢复回执与历史一致性。它是可跟踪的修复方案，不能写成已发行能力。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-js/pull/2673" target="_blank" rel="noreferrer">1</a></p><p><span id="o14"></span></p><h3 id="o14-openhands-系统-goal-不能代替人的回答" tabindex="-1">O14 OpenHands：系统 goal 不能代替人的回答 <a class="header-anchor" href="#o14-openhands-系统-goal-不能代替人的回答" aria-label="Permalink to &quot;O14 OpenHands：系统 goal 不能代替人的回答&quot;">​</a></h3><p>11月16日 16:06 / 20:23 UTC，实验性 ask_user 与后续 #6902 已合入。待回答问题优先于 Stop hook 和完成循环；goal start/resume 遇 pending_ask 拒绝，生成消息带 sender=goal，不能被当成人的回答。重复选项用序号区分。上游提供 HTTP/WebSocket 与真实模型证据，但我们未安装实测；功能仍受实验开关控制。</p><p>原始来源：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6902" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6852" target="_blank" rel="noreferrer">2</a></p><p><span id="o15"></span></p><h3 id="o15-openhands-更正消息而不改写原始事件" tabindex="-1">O15 OpenHands：更正消息而不改写原始事件 <a class="header-anchor" href="#o15-openhands-更正消息而不改写原始事件" aria-label="Permalink to &quot;O15 OpenHands：更正消息而不改写原始事件&quot;">​</a></h3><p>11月16日 20:46 UTC，#6876 已合入，message_edits 默认关闭。Agent 可更正自己仍在可见上下文中的旧消息，新增 MessageEditEvent，客户端显示最近编辑；原 EventLog 保持追加，模型仍看到原消息及 edit_message 调用/结果。已被压缩出视图的消息不能编辑。这是展示更正与原始证据分离的具体实现。</p><p>原始来源：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6876" target="_blank" rel="noreferrer">1</a></p><p><span id="o16"></span></p><h3 id="o16-openhands-运行中加-mcp-与首轮就绪屏障" tabindex="-1">O16 OpenHands：运行中加 MCP 与首轮就绪屏障 <a class="header-anchor" href="#o16-openhands-运行中加-mcp-与首轮就绪屏障" aria-label="Permalink to &quot;O16 OpenHands：运行中加 MCP 与首轮就绪屏障&quot;">​</a></h3><p>11月16日 15:59 / 19:11 UTC，两项 PR 已合入。运行中 add_mcp_servers 只支持新增，拒绝 legacy / SSE，不支持移除、替换或写回全局配置；新增工具带服务器名前缀，避免重命名旧工具。Agent Server 以1秒启动预算先返回会话，但首个模型步骤仍等服务器就绪或失败，不能说模型已提前具备所有工具。SDK 默认继续全等待。</p><p>原始来源：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6802" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6877" target="_blank" rel="noreferrer">2</a></p><p><span id="o17"></span></p><h3 id="o17-openhands-组织可关掉默认公共技能与目录" tabindex="-1">O17 OpenHands：组织可关掉默认公共技能与目录 <a class="header-anchor" href="#o17-openhands-组织可关掉默认公共技能与目录" aria-label="Permalink to &quot;O17 OpenHands：组织可关掉默认公共技能与目录&quot;">​</a></h3><p>11月16日 11:47 UTC，#6739 已合入。OH_PUBLIC_SKILLS_ENABLED=false 关闭默认公共 skills，OH_PUBLIC_CATALOG_ENABLED=false 关闭默认公共技能/插件目录抓取；组织注册市场、客户端提供和已持久化技能继续保留。两项默认 true，冲突优先级另议。它是来源控制开关，不是完整企业白名单或技能安全验证。</p><p>原始来源：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6739" target="_blank" rel="noreferrer">1</a></p><p><span id="o18"></span></p><h3 id="o18-github-mcp-server-2-2-技能目录与受控自动化" tabindex="-1">O18 GitHub MCP Server 2.2：技能目录与受控自动化 <a class="header-anchor" href="#o18-github-mcp-server-2-2-技能目录与受控自动化" aria-label="Permalink to &quot;O18 GitHub MCP Server 2.2：技能目录与受控自动化&quot;">​</a></h3><p>11月16日 23:30 UTC，v2.2.0 已发行。18 个 bundled workflows 通过 opt-in skills 暴露，并按当前可用工具筛选；这不是运行授权。#3719 的11个自动化读写/运行工具需非默认 toolset 和 agent_automations 开关；变更需与精确请求绑定、10分钟过期的表单接受，缺少状态保护则拒绝，HTTP 无保护时隐藏变更工具。hide_secret=true 可让告警 API 不取回秘密值，但默认未开启。技能和脱敏 PR 较早合入，此轮新增是正式发行。</p><p>原始来源：<a href="https://github.com/github/github-mcp-server/releases/tag/v2.2.0" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/github/github-mcp-server/pull/3719" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/github/github-mcp-server/pull/3685" target="_blank" rel="noreferrer">3</a> · <a href="https://github.com/github/github-mcp-server/pull/3838" target="_blank" rel="noreferrer">4</a></p><p><span id="o19"></span></p><h3 id="o19-copilot-企业控制扩展来源-而不是只禁用能力" tabindex="-1">O19 Copilot：企业控制扩展来源，而不是只禁用能力 <a class="header-anchor" href="#o19-copilot-企业控制扩展来源-而不是只禁用能力" aria-label="Permalink to &quot;O19 Copilot：企业控制扩展来源，而不是只禁用能力&quot;">​</a></h3><p>11月16日官方公告：企业管理员可用 strictPluginOnlyCustomization 按 skills、agents、hooks、MCP、可执行扩展五类限制独立用户/项目配置，只接受插件或 managed settings。插件来源仍需配合 strictKnownMarketplaces；plugin-only 本身不是市场白名单。适用 Enterprise Cloud 下企业发放的 Business/Enterprise 席位。已公告可用，未在本地企业租户验证。</p><p>原始来源：<a href="https://github.blog/changelog/2026-11-16-control-where-github-copilot-customizations-come-from/" target="_blank" rel="noreferrer">1</a></p><p><span id="o20"></span></p><h3 id="o20-copilot-旧-local-harness-计划退役-迁移不自动带来沙箱" tabindex="-1">O20 Copilot：旧 Local harness 计划退役，迁移不自动带来沙箱 <a class="header-anchor" href="#o20-copilot-旧-local-harness-计划退役-迁移不自动带来沙箱" aria-label="Permalink to &quot;O20 Copilot：旧 Local harness 计划退役，迁移不自动带来沙箱&quot;">​</a></h3><p>11月16日公告：VS Code 1.146 废弃旧 Local harness，计划2027年2月移除；Copilot harness 从1.143起已为新会话默认，和 CLI / App 共用运行时。会话跨编辑器与 Agents 窗口延续依赖 Agent Host 存活，编辑器工具还需连接编辑器。选择新 harness 不会自动开启沙箱，也不保证所有定制兼容。这里报告的是迁移公告，不是已完成退役。</p><p>原始来源：<a href="https://github.blog/changelog/2026-11-16-vs-code-retires-the-local-harness-in-february-2027/" target="_blank" rel="noreferrer">1</a></p><p><span id="o21"></span></p><h3 id="o21-copilot-产品-手机续跑、会话内重新认证和分钟级调度" tabindex="-1">O21 Copilot 产品：手机续跑、会话内重新认证和分钟级调度 <a class="header-anchor" href="#o21-copilot-产品-手机续跑、会话内重新认证和分钟级调度" aria-label="Permalink to &quot;O21 Copilot 产品：手机续跑、会话内重新认证和分钟级调度&quot;">​</a></h3><p>11月16日官方周报列出 Cloud/Codespace 会话转手机、会话内 MCP 重新登录后续跑，以及 Project automation 分钟级/自定义 cron。VS Code 跨工作区 Inbox 按需人介入排序仍为实验功能。GHES 接入 App 已 GA，但 GHES 不支持 cloud session。它是已有周内功能的首次本轮官方核查，不重复声称今日新合入。学习移动端异常处理价值高；产品竞争风险上升，保留持续观察。</p><p>原始来源：<a href="https://github.blog/changelog/2026-11-16-github-copilot-weekly-releases-november-9/" target="_blank" rel="noreferrer">1</a></p><p><span id="o22"></span></p><h3 id="o22-paperclip-stop-要等准备阶段结算证明" tabindex="-1">O22 Paperclip：Stop 要等准备阶段结算证明 <a class="header-anchor" href="#o22-paperclip-stop-要等准备阶段结算证明" aria-label="Permalink to &quot;O22 Paperclip：Stop 要等准备阶段结算证明&quot;">​</a></h3><p>11月16日 20:38 UTC，#21906 已合入。准备阶段停止、尚未 adapter dispatch 时，原来已保存“未启动模型”的证明，却把 Stop receipt 留在 requested。现在在 run 锁下检查无 handedOffAt 等条件，先写 preparation_settled 再确认停止；已有交接标记的旧控制器仍保留 recovery hold。Stop 不自行重开任务，之后留言走正常准入。学习价值与恢复竞争风险高，Paperclip 保持主雷达重点。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/21906" target="_blank" rel="noreferrer">1</a></p><p><span id="o23"></span></p><h3 id="o23-paperclip-接管原进程时延续凭证入口" tabindex="-1">O23 Paperclip：接管原进程时延续凭证入口 <a class="header-anchor" href="#o23-paperclip-接管原进程时延续凭证入口" aria-label="Permalink to &quot;O23 Paperclip：接管原进程时延续凭证入口&quot;">​</a></h3><p>11月16日 20:13 UTC，#21928 已合入。原生 provider 进程在控制器重启后仍引用旧 PATH 下的 gh/git launcher；旧控制器清理随机目录使其“看似令牌过期”。修复改为 session/task 稳定 launcher 目录，并在新控制器接管时重新装配。它修复访问连续性，仍须另查撤权和凭证期限；不代表给旧进程永久授权。学习价值高，雷达补充身份恢复维度。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/21928" target="_blank" rel="noreferrer">1</a></p><p><span id="o24"></span></p><h3 id="o24-paperclip-并行回执预留溢出只拒绝超量调用" tabindex="-1">O24 Paperclip：并行回执预留溢出只拒绝超量调用 <a class="header-anchor" href="#o24-paperclip-并行回执预留溢出只拒绝超量调用" aria-label="Permalink to &quot;O24 Paperclip：并行回执预留溢出只拒绝超量调用&quot;">​</a></h3><p>11月16日 18:53 UTC，#21913 已合入。每待决调用预留768 KiB、每轮8 MiB，短时并行预留超额过去会停止整轮并要求人工 Retry；现在仅把超额调用作为可重试拒绝，实际已持有字节超限仍可停止整轮，并加新会话续跑后备。该阈值是这个实现的预算，不是通用最佳值。学习背压与持久回执区分，恢复竞争风险上调。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/21913" target="_blank" rel="noreferrer">1</a></p><p><span id="o25"></span></p><h3 id="o25-paperclip-合并唤醒不能丢人的留言与子任务完成原因" tabindex="-1">O25 Paperclip：合并唤醒不能丢人的留言与子任务完成原因 <a class="header-anchor" href="#o25-paperclip-合并唤醒不能丢人的留言与子任务完成原因" aria-label="Permalink to &quot;O25 Paperclip：合并唤醒不能丢人的留言与子任务完成原因&quot;">​</a></h3><p>11月16日 16:10 / 16:37 至17日 01:59 UTC，三项 PR 已合入。人的留言合并进 system wake 后，按实际留言作者决定重开已完成任务；保存全部合并原因，让待消费子任务结果继续阻止父任务过早完成。已成功 finalize 的 blocker 若后续 workspace 操作已结算、所属 run 已结束，可释放依赖；失败且未补成功的 finalize 仍阻挡。#21918 明确原测试中的特定 finish 延迟归因不成立，不能把它写成已证事故。学习价值高，主雷达继续重点跟踪。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/21914" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/paperclipai/paperclip/pull/21918" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/paperclipai/paperclip/pull/21948" target="_blank" rel="noreferrer">3</a></p><p><span id="o26"></span></p><h3 id="o26-orkas-正式发行可恢复创作工作流-仍保留验收缺口" tabindex="-1">O26 Orkas：正式发行可恢复创作工作流，仍保留验收缺口 <a class="header-anchor" href="#o26-orkas-正式发行可恢复创作工作流-仍保留验收缺口" aria-label="Permalink to &quot;O26 Orkas：正式发行可恢复创作工作流，仍保留验收缺口&quot;">​</a></h3><p>11月16日 15:28 UTC，v2026.11.16 已发行，#223 已合入：Content/电商工作台、可恢复视频时间线、图像/PDF/Office 处理、会话/项目草稿与本地任务恢复。上游仍记录事件循环796.4 ms对500 ms、另一延迟1377.3 ms对1000 ms、初始上下文超过20K、退出 IPC 与文档恢复等缺口，并明确没有新增实体 Windows/Linux 或签名安装包验收。MIT 源码版不含安装包版的共享项目、云同步和网页应用发布。学习价值高、交付能力竞争风险上升；成熟度仍需独立体验。</p><p>原始来源：<a href="https://github.com/Orkas-AI/Orkas/releases/tag/v2026.11.16" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/Orkas-AI/Orkas/pull/223" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/Orkas-AI/Orkas/blob/main/README.md" target="_blank" rel="noreferrer">3</a></p><p><span id="o27"></span></p><h3 id="o27-paradev-按-bundle-发布不可变-agent-工具盘" tabindex="-1">O27 Paradev：按 bundle 发布不可变 Agent 工具盘 <a class="header-anchor" href="#o27-paradev-按-bundle-发布不可变-agent-工具盘" aria-label="Permalink to &quot;O27 Paradev：按 bundle 发布不可变 Agent 工具盘&quot;">​</a></h3><p>11月17日 01:21 / 02:41 UTC，两项 PR 已合入。Agent CLI 以 bundle/region 的只读 Vercel Drive 共享，按组织开关启用；发布先停止写入 builder 再供快照挂载，避免仍被写入的盘产生损坏。后续从旧盘 fork、只下载变化项、manifest 最后写，逐 Agent smoke check；失败时明确 kept-previous 或 dropped，不把旧版本冒充目标版本。MIT 项目，云实现有 Vercel 成本与依赖。学习价值高，运维/分发竞争风险上升；原 Superset 雷达归属保留，核验后的 canonical 是 ParadevAI/Paradev。</p><p>原始来源：<a href="https://github.com/ParadevAI/Paradev/pull/9844" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9861" target="_blank" rel="noreferrer">2</a></p><p><span id="o28"></span></p><h3 id="o28-paradev-只在确认动态-oauth-客户端失效时重注册" tabindex="-1">O28 Paradev：只在确认动态 OAuth 客户端失效时重注册 <a class="header-anchor" href="#o28-paradev-只在确认动态-oauth-客户端失效时重注册" aria-label="Permalink to &quot;O28 Paradev：只在确认动态 OAuth 客户端失效时重注册&quot;">​</a></h3><p>11月16日 23:10 UTC，#9848 已合入。复用动态注册客户端前，探测授权端点；仅“4xx且正文明确指向 client 问题”才忘记旧注册并重建，网络失败、无关403、5xx继续保留，避免把已有授权绑错客户端。每次复用连接多一个最长5秒 GET。上游仅手查请求与本地测试，未部署端到端验收。学习恢复判据价值高，接入可靠性竞争风险中等；持续观察。</p><p>原始来源：<a href="https://github.com/ParadevAI/Paradev/pull/9848" target="_blank" rel="noreferrer">1</a></p><p><span id="o29"></span></p><h3 id="o29-paradev-会话代际防止旧休眠事件覆盖新唤醒" tabindex="-1">O29 Paradev：会话代际防止旧休眠事件覆盖新唤醒 <a class="header-anchor" href="#o29-paradev-会话代际防止旧休眠事件覆盖新唤醒" aria-label="Permalink to &quot;O29 Paradev：会话代际防止旧休眠事件覆盖新唤醒&quot;">​</a></h3><p>11月16日 04:18 UTC，#9800 已合入。cloud workspace 写 sandbox_session_id / expires_at，以到期检查加30分钟 reconcile 补偿平台缺失事件；asleep 写入绑定 session ID，避免旧停止事件把新唤醒实例标成休眠。数据库先 expand 再兼容新旧状态，后续迁移再清理，不能在线直接重命名破坏旧 API。上游称 TLA+ 找到竞态，非本轮完成模型验证。学习价值高，雷达补充运行代际与升级兼容。</p><p>原始来源：<a href="https://github.com/ParadevAI/Paradev/pull/9800" target="_blank" rel="noreferrer">1</a></p><p><span id="o30"></span></p><h3 id="o30-orca-读取会话不唤醒-执行回执记实际模型" tabindex="-1">O30 Orca：读取会话不唤醒，执行回执记实际模型 <a class="header-anchor" href="#o30-orca-读取会话不唤醒-执行回执记实际模型" aria-label="Permalink to &quot;O30 Orca：读取会话不唤醒，执行回执记实际模型&quot;">​</a></h3><p>11月16日 22:07 / 23:11 UTC，两项 PR 已合入。orca agent list/show/read 通过 Orca session ID 读取宿主会话和真实 transcript，不抓屏、不启动或唤醒 Agent；跨宿主需 environment，休眠终端列表与部分 WSL 情形仍有限制。chat worker 回执改记最终采用的 model/effort，而不只记录请求参数；terminal 模式未知值仍保留 null。学习可观测性价值高，治理竞争风险中等；与 O2 一并提高跟踪优先级。</p><p>原始来源：<a href="https://github.com/stablyai/orca/pull/41815" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/stablyai/orca/pull/43276" target="_blank" rel="noreferrer">2</a></p><p><span id="o31"></span></p><h3 id="o31-crewai-超时准时返回-但不能声称工作线程已停止" tabindex="-1">O31 CrewAI：超时准时返回，但不能声称工作线程已停止 <a class="header-anchor" href="#o31-crewai-超时准时返回-但不能声称工作线程已停止" aria-label="Permalink to &quot;O31 CrewAI：超时准时返回，但不能声称工作线程已停止&quot;">​</a></h3><p>11月16日 16:53 UTC，#9324 已合入。同步 max_execution_time 不再因 ThreadPoolExecutor 退出时等待工作线程而拖延 TimeoutError，改用 shutdown(wait=False, cancel_futures=True)。Python 无法强杀已经运行的线程，工具仍可能后台继续。对数字员工的重要含义是：收到超时后重派任务，可能与旧执行重叠；这条事实不能被改写为“已解决所有取消副作用”。</p><p>原始来源：<a href="https://github.com/crewAIInc/crewAI/pull/9324" target="_blank" rel="noreferrer">1</a></p><p><span id="o32"></span></p><h3 id="o32-crewai-长期记忆数量不能取截断扫描行数" tabindex="-1">O32 CrewAI：长期记忆数量不能取截断扫描行数 <a class="header-anchor" href="#o32-crewai-长期记忆数量不能取截断扫描行数" aria-label="Permalink to &quot;O32 CrewAI：长期记忆数量不能取截断扫描行数&quot;">​</a></h3><p>11月16日 03:31 UTC，#9391 已合入。LanceDB scope 原来把最多50,000行元数据扫描结果当总量，50,001条以上的团队记忆少算；改用同一前缀过滤的原生 count_rows。分类/最早最晚时间等元数据仍来自有上限扫描，不能推成整个统计面都已完整。它提供长期数字员工运营数据完整性的反例，非权限隔离证明。</p><p>原始来源：<a href="https://github.com/crewAIInc/crewAI/pull/9391" target="_blank" rel="noreferrer">1</a></p><p><span id="o33"></span></p><h3 id="o33-adk-委派结果交付与远端任务续跑仍有开放修复" tabindex="-1">O33 ADK：委派结果交付与远端任务续跑仍有开放修复 <a class="header-anchor" href="#o33-adk-委派结果交付与远端任务续跑仍有开放修复" aria-label="Permalink to &quot;O33 ADK：委派结果交付与远端任务续跑仍有开放修复&quot;">​</a></h3><p>#8185 于11月16日新建，仍 OPEN：child 输出进入事件流，却未进入父 ctx.output，下游得到 None；拟修 use_as_output 传播。#7849 是10月创建、11月16日有更新的 OPEN 修复：暂停调用者恢复时先 GetTask 取已完成 task-mode peer 结果，避免向终态任务再发消息；plain chat、失败/取消分支不在相同修复范围。两项均未合入；上游测试主张不等于本地通过。</p><p>原始来源：<a href="https://github.com/google/adk-python/pull/8185" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/google/adk-python/pull/7849" target="_blank" rel="noreferrer">2</a></p><p><span id="o34"></span></p><h3 id="o34-langfuse-批量删除合并审计但保留逐对象可追溯" tabindex="-1">O34 Langfuse：批量删除合并审计但保留逐对象可追溯 <a class="header-anchor" href="#o34-langfuse-批量删除合并审计但保留逐对象可追溯" aria-label="Permalink to &quot;O34 Langfuse：批量删除合并审计但保留逐对象可追溯&quot;">​</a></h3><p>11月16日 17:26 UTC，#20322 已合入。1,000个 trace 删除从1,000个 actor日志/审计行变成一个 project deleteTraces 事件，持久保存完整 traceIds；typed resource_refs 从快照派生，live 与 backfill 一致，仍可按 trace 查询。减少审计成本的前提是对象集合完整且可重建，不是只存一行“批量完成”。不据合入时间推定已进入当天4.81发行包。</p><p>原始来源：<a href="https://github.com/langfuse/langfuse/pull/20322" target="_blank" rel="noreferrer">1</a></p><p><span id="o35"></span></p><h3 id="o35-langfuse-审计迁移有固定终点、提交等待和稳定-id" tabindex="-1">O35 Langfuse：审计迁移有固定终点、提交等待和稳定 ID <a class="header-anchor" href="#o35-langfuse-审计迁移有固定终点、提交等待和稳定-id" aria-label="Permalink to &quot;O35 Langfuse：审计迁移有固定终点、提交等待和稳定 ID&quot;">​</a></h3><p>11月16日 14:15 UTC 合入、16:26 UTC 的 v4.81.0 发行说明列出审计 Postgres→ClickHouse 回填。每500行存(created_at,id)游标，等待5分钟提交，固定 copyUntil 并保留10分钟重叠，使用与实时 staging 相同事件 ID。跳过已写副本避免覆盖 actor 元数据；无法映射行计 failedRows 而非假装全部成功。读侧迁移 PR 仍另行推进，不把复制完成等同所有查询切换。</p><p>原始来源：<a href="https://github.com/langfuse/langfuse/pull/18958" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/langfuse/langfuse/releases/tag/v4.81.0" target="_blank" rel="noreferrer">2</a></p><p><span id="o36"></span></p><h3 id="o36-赵越-auditable-0-5-显式区分审计阶段与方法类型" tabindex="-1">O36 赵越 auditable 0.5：显式区分审计阶段与方法类型 <a class="header-anchor" href="#o36-赵越-auditable-0-5-显式区分审计阶段与方法类型" aria-label="Permalink to &quot;O36 赵越 auditable 0.5：显式区分审计阶段与方法类型&quot;">​</a></h3><p>11月16日 01:28 UTC，v0.5.0 已发行，晚于上轮执行起点，且未计入昨天日档。Row / leaderboard 新增 Type、Algorithm，并在跨阶段榜单展示 PRE/LIVE/POST；Custom、Baseline、Oracle 分类边界明确，README 榜单从 golden files 生成并做漂移检查。主要是基准可解释性、文档/API 表格契约更新，不能宣传成新增一批检测算法或本地获得更高分；按列位置解析旧表格的脚本需迁移。</p><p>原始来源：<a href="https://github.com/yzhao062/auditable/releases/tag/v0.5.0" target="_blank" rel="noreferrer">1</a></p><p><span id="o37"></span></p><h3 id="o37-phoenix-otel-采样设置被忽略必须可见" tabindex="-1">O37 Phoenix OTEL：采样设置被忽略必须可见 <a class="header-anchor" href="#o37-phoenix-otel-采样设置被忽略必须可见" aria-label="Permalink to &quot;O37 Phoenix OTEL：采样设置被忽略必须可见&quot;">​</a></h3><p>11月17日 01:58 UTC 合入，02:11 UTC 的 @arizeai/phoenix-otel 3.1.0 对应发行。register 对被忽略的 OTEL_TRACES_SAMPLER / SPAN 等环境变量发警告，新增 sampler/spanLimits；旧式位置参数 processor 立即抛明确错误，避免静默丢 span。上游包级探针指出 always_off 被忽略时仍可能导出数据；浏览器构建未实测。治理研究要同时关注“漏审计”和“以为关闭却仍导出”。</p><p>原始来源：<a href="https://github.com/Arize-ai/phoenix/pull/17837" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/Arize-ai/phoenix/releases/tag/%40arizeai/phoenix-otel%403.1.0" target="_blank" rel="noreferrer">2</a></p><p><span id="o38"></span></p><h3 id="o38-gemini-cli-受信-mcp-配置还要检查其可执行目标" tabindex="-1">O38 Gemini CLI：受信 MCP 配置还要检查其可执行目标 <a class="header-anchor" href="#o38-gemini-cli-受信-mcp-配置还要检查其可执行目标" aria-label="Permalink to &quot;O38 Gemini CLI：受信 MCP 配置还要检查其可执行目标&quot;">​</a></h3><p>11月16日 17:56 UTC，#30283 已合入。系统 MCP 配置文件自身可信并不足够：若引用脚本或父目录可被低权限用户改写，就能借 allowlist 身份执行不同程序。新增本地命令/解释器脚本的所有权与写权限检查，不安全条目跳过并警告，还阻止低优先级 workspace 同名定义顶替。不是仅校验 JSON 文件即可完成企业信任。</p><p>原始来源：<a href="https://github.com/google-gemini/gemini-cli/pull/30283" target="_blank" rel="noreferrer">1</a></p><p><span id="o39"></span></p><h3 id="o39-openhands-1-41-已有-secret-不再自动冒充一次新保存" tabindex="-1">O39 OpenHands 1.41：已有 secret 不再自动冒充一次新保存 <a class="header-anchor" href="#o39-openhands-1-41-已有-secret-不再自动冒充一次新保存" aria-label="Permalink to &quot;O39 OpenHands 1.41：已有 secret 不再自动冒充一次新保存&quot;">​</a></h3><p>11月16日 13:41 UTC，#19062 已合入并列入20:46 UTC 的1.41.0发行。request_secret 命中已有名称原来直接回 saved、取消待决卡片；现在必须等人保存或取消，只允许覆盖被请求的名称，不读取或预填旧值，取消不写入并回 not_saved。核心研究者 Graham Neubig 作为需求发起与审阅参与者在 PR 中明确出现。上游真实 Canvas 验证不能算本轮本地验收。</p><p>原始来源：<a href="https://github.com/OpenHands/OpenHands/pull/19062" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/OpenHands/OpenHands/releases/tag/v1.41.0" target="_blank" rel="noreferrer">2</a></p><p><span id="o40"></span></p><h3 id="o40-orca-开放修复-撤权后清理不应重新授予访问" tabindex="-1">O40 Orca 开放修复：撤权后清理不应重新授予访问 <a class="header-anchor" href="#o40-orca-开放修复-撤权后清理不应重新授予访问" aria-label="Permalink to &quot;O40 Orca 开放修复：撤权后清理不应重新授予访问&quot;">​</a></h3><p>11月17日 02:17 UTC 新建，#43371 仍 OPEN、非 DRAFT。拟在 worktree 已撤销或移除后，用原路径只查已有 watcher 的内存键并关闭它，不因重新授权失败阻塞清理；不会创建新 watcher 或读文件。POSIX / 本机路径为范围，Windows与SSH不变。学习撤权后资源回收价值高，竞争风险暂为方案级；持续观察，不写成已修复。</p><p>原始来源：<a href="https://github.com/stablyai/orca/pull/43371" target="_blank" rel="noreferrer">1</a></p><p><span id="o41"></span></p><h3 id="o41-adk-开放修复-不同日志出口脱敏不一致" tabindex="-1">O41 ADK 开放修复：不同日志出口脱敏不一致 <a class="header-anchor" href="#o41-adk-开放修复-不同日志出口脱敏不一致" aria-label="Permalink to &quot;O41 ADK 开放修复：不同日志出口脱敏不一致&quot;">​</a></h3><p>11月17日 01:22 UTC 新建，#8195 仍 OPEN、非 DRAFT。BigQuery analytics 漏掉 auth_code、code_verifier、auth_response_uri 等字段，而 DebugLogging 已脱敏；拟统一四个键及 URL/文本路径。作者只在脱敏函数层复现，未运行真实 OAuth→BigQuery；private_key_id 是标识符不是秘密，需保留这一边界。新增测试6过、全文件仍10失败，不能写成全面验证通过或已发生实际泄漏。</p><p>原始来源：<a href="https://github.com/google/adk-python/pull/8195" target="_blank" rel="noreferrer">1</a></p><p><span id="o42"></span></p><h3 id="o42-mini-swe-agent-并行样本轨迹必须独立落盘" tabindex="-1">O42 mini-SWE-agent：并行样本轨迹必须独立落盘 <a class="header-anchor" href="#o42-mini-swe-agent-并行样本轨迹必须独立落盘" aria-label="Permalink to &quot;O42 mini-SWE-agent：并行样本轨迹必须独立落盘&quot;">​</a></h3><p>11月16日 21:54 UTC 新建，#1051 仍 OPEN、非 DRAFT。共享 agent.output_path 会令并行 SWE-bench worker 写同一文件；默认配置又只在结束写实例轨迹。拟将逐步保存绑定实例路径，异常后保留已完成步骤。作者运行本地确定性双 worker，未跑供应商或容器集成；重跑仍依 preds.json，不支持从这些轨迹直接恢复。价值是评测证据隔离，不是新增 checkpoint resume 能力。</p><p>原始来源：<a href="https://github.com/SWE-agent/mini-swe-agent/pull/1051" target="_blank" rel="noreferrer">1</a></p><p><span id="o43"></span></p><h3 id="o43-codex-沙箱兼容-ssh-时保留已知主机密钥验证" tabindex="-1">O43 Codex：沙箱兼容 SSH 时保留已知主机密钥验证 <a class="header-anchor" href="#o43-codex-沙箱兼容-ssh-时保留已知主机密钥验证" aria-label="Permalink to &quot;O43 Codex：沙箱兼容 SSH 时保留已知主机密钥验证&quot;">​</a></h3><p>11月17日 02:33 UTC，#61947 已合入。用户命名空间会把宿主 root 拥有的 SSH drop-in 映射成 nobody，导致 OpenSSH 拒绝配置；文件受限命令默认把 /etc/ssh/ssh_config.d 遮成只读空目录，保留显式读取和重叠写入授权。被遮蔽的 KnownHostsCommand 等不再运行，但上游握手回归仍验证主机密钥变化被拒绝。兼容性修复有配置语义代价，不等于取消 SSH 身份验证。</p><p>原始来源：<a href="https://github.com/openai/codex/pull/61947" target="_blank" rel="noreferrer">1</a></p><p><span id="o44"></span></p><h3 id="o44-a2a-的-aae-扩展提案-授权判定与技能执行结果分开" tabindex="-1">O44 A2A 的 AAE 扩展提案：授权判定与技能执行结果分开 <a class="header-anchor" href="#o44-a2a-的-aae-扩展提案-授权判定与技能执行结果分开" aria-label="Permalink to &quot;O44 A2A 的 AAE 扩展提案：授权判定与技能执行结果分开&quot;">​</a></h3><p>11月16日 13:17 UTC，OPEN Issue #2391 新增提案者状态说明：以 request_digest 绑定冻结请求；对照“请求获准但 skill 失败”和“请求被拒、skill 从未调用”；补充 deferred decision / ratification 与各实现来源声明。hummbl 的 clean_room 24/24 是参与者报告，结果入库 PR 当时待提交；作者仍请求维护者赞助 experimental 扩展仓库，挑战/拒绝映射尚无维护者定论。本轮未重算向量或完成线上 wire 互操作。它是 A2A 技能调用前授权的互补协议研究线索，不是 A2A 核心标准，也不能直接要求 FCoP 照搬。</p><p>原始来源：<a href="https://github.com/a2aproject/A2A/issues/2391" target="_blank" rel="noreferrer">1</a> · <a href="https://github.com/a2aproject/A2A/issues/2391#issuecomment-6917526766" target="_blank" rel="noreferrer">2</a> · <a href="https://github.com/a2aproject/A2A/issues/2391#issuecomment-6917489248" target="_blank" rel="noreferrer">3</a></p><h2 id="研究分析" tabindex="-1">研究分析 <a class="header-anchor" href="#研究分析" aria-label="Permalink to &quot;研究分析&quot;">​</a></h2><h3 id="a1-优先研究-消息来源不能升级为执行授权" tabindex="-1">A1 优先研究：消息来源不能升级为执行授权 <a class="header-anchor" href="#a1-优先研究-消息来源不能升级为执行授权" aria-label="Permalink to &quot;A1 优先研究：消息来源不能升级为执行授权&quot;">​</a></h3><p>依据：<a href="#o1">O1</a>、<a href="#o2">O2</a>、<a href="#o3">O3</a>、<a href="#o4">O4</a>、<a href="#o5">O5</a>、<a href="#o10">O10</a>、<a href="#o14">O14</a>、<a href="#o18">O18</a>、<a href="#o19">O19</a>、<a href="#o38">O38</a>、<a href="#o39">O39</a>、<a href="#o44">O44</a>。</p><p>已有证据支持：Orca、OpenHands、Agents SDK 和 GitHub MCP 分别处理了 Agent 来信、系统 goal、人的决定、精确请求接受的来源差异；Codex 又加入证据截面。企业治理不只是工具 allow/deny，还要知道谁说了什么、批准的究竟是哪一个动作。Orca 仓库永久信任则是另一种取舍，不能与动作级授权等同。待验证推断：CodeFlowMu 的岗位委派、任务留言、人工批准若在适配时都变成普通 user 文本，可能丢掉 authority 边界；本轮未确认本地存在此缺陷。实验候选 P0：同一测试上传动作分别由员工来信、系统提醒、人的明确批准触发，再加入过期批准、参数被替换和批准后撤权。验收看被阻止的副作用、拒绝原因和实际批准绑定，不能只看审查模型说“安全”。FCoP 可比较发送者/委派/证据的表达；身份认证、当前权限和调用拦截属于 Runtime/适配层职责。代价是稳定身份、请求摘要与授权版本的管理，并可能增加人工等待。互动议题：跨 Agent 引用一段真实人的旧授权，如何避免在新请求中被重用？</p><h3 id="a2-优先研究-停止、超时、接管和结算必须分开验证" tabindex="-1">A2 优先研究：停止、超时、接管和结算必须分开验证 <a class="header-anchor" href="#a2-优先研究-停止、超时、接管和结算必须分开验证" aria-label="Permalink to &quot;A2 优先研究：停止、超时、接管和结算必须分开验证&quot;">​</a></h3><p>依据：<a href="#o5">O5</a>、<a href="#o6">O6</a>、<a href="#o8">O8</a>、<a href="#o9">O9</a>、<a href="#o13">O13</a>、<a href="#o22">O22</a>、<a href="#o23">O23</a>、<a href="#o24">O24</a>、<a href="#o25">O25</a>、<a href="#o29">O29</a>、<a href="#o31">O31</a>、<a href="#o33">O33</a>、<a href="#o40">O40</a>。</p><p>已有证据支持：CrewAI 的按时 TimeoutError 不会杀掉已运行线程；Paperclip 则区分请求停止、交接、证明未启动、结算；Paradev 以 session 代际阻止旧停止事件覆盖新实例。这些事实支持“调用者返回”和“执行已停止”需要分开核实，不证明所有框架都存在同一故障。实验候选 P0：测试员工执行一个带唯一 ID 的可计数本地动作，在准备前、交接后、动作完成但回执未落盘、控制器重启、旧终态晚到五处中断；另做超时后转交备用员工。记录重复副作用数、无归属进程、未结算回执、恢复时延和是否需人工判断。目标阈值需实验前定义，不能预报通过。FCoP 可对比任务/事件/结果与证据引用的契约；lease、owner generation、重试策略和进程终止放在 Runtime。代价是故障注入与不确定状态保留，不能靠把所有失败自动重试来省略。互动议题：已交给外部工具但没有可判定结果时，何种证据足够恢复而不重复执行？</p><h3 id="a3-审计要能解释缺失、删改、聚合与历史窗口" tabindex="-1">A3 审计要能解释缺失、删改、聚合与历史窗口 <a class="header-anchor" href="#a3-审计要能解释缺失、删改、聚合与历史窗口" aria-label="Permalink to &quot;A3 审计要能解释缺失、删改、聚合与历史窗口&quot;">​</a></h3><p>依据：<a href="#o1">O1</a>、<a href="#o7">O7</a>、<a href="#o11">O11</a>、<a href="#o12">O12</a>、<a href="#o15">O15</a>、<a href="#o32">O32</a>、<a href="#o34">O34</a>、<a href="#o35">O35</a>、<a href="#o36">O36</a>、<a href="#o37">O37</a>、<a href="#o41">O41</a>、<a href="#o42">O42</a>。</p><p>已有证据支持：审计不是“存了日志”就结束。OpenHands 用追加更正保留原记录，Langfuse 聚合仍保留对象集合和稳定 ID，Phoenix 同时暴露漏发与不该导出的遥测风险；Kyvvu 则公开有限历史窗口。待验证推断：若数字员工仪表盘只呈现最终摘要，失败成本、历史策略边界和证据缺口可能被掩盖，但本轮无本地故障证据。实验候选 P1：在离线轨迹中插入一条坏 span、一次脱敏编辑、跨窗口 secret-read、1,000对象批量动作、失败模型用量与并行 worker 文件写入；核验原记录可追溯、更正可解释、对象集合完整、丢失有计数。auditable 0.5 可作分阶段方法分类与对照工具候选，不能把 PRE/LIVE/POST 分数混成一个安全承诺。FCoP 比较证据引用与更正语义；数据采集、存储、导出权限和保留策略归 Runtime/运维。代价是存储、索引、隐私与可查询性的权衡。互动议题：聚合审计如何证明没有漏掉对象，而不把敏感值再次写进审计？</p><h3 id="a4-优先研究-协作完成需要结果被交付并消费" tabindex="-1">A4 优先研究：协作完成需要结果被交付并消费 <a class="header-anchor" href="#a4-优先研究-协作完成需要结果被交付并消费" aria-label="Permalink to &quot;A4 优先研究：协作完成需要结果被交付并消费&quot;">​</a></h3><p>依据：<a href="#o6">O6</a>、<a href="#o9">O9</a>、<a href="#o13">O13</a>、<a href="#o14">O14</a>、<a href="#o16">O16</a>、<a href="#o25">O25</a>、<a href="#o30">O30</a>、<a href="#o33">O33</a>、<a href="#o44">O44</a>。</p><p>已有证据支持：ADK 的事件流有 child output 不代表父上下文拿到了结果；Paperclip 合并 wake 后要保留子任务完成原因；Codex 明确 accepted 不等于 wake。可比较的对象是消息接受、执行启动、工件产生、交接、父任务消费、独立验收等不同阶段。实验候选 P0：用“采购研究→方案汇总→独立复核”的三岗位流程，主动打乱消息与工件次序、重复通知、暂停父任务、让子任务先完成再恢复；核验每份结果进入正确版本的父上下文、最终报告没有漏项，审阅员工能独立拒绝不完整交付。FCoP 在此可和 A2A 的 task/artifact/授权结果、AAE 的 request_digest 作语义对照；MCP 的工具调用就绪与技能目录属于互补接入层，不把它们都叫同层竞品。AAE 跨实现数字仍是参与者主张，须独立重算并区分离线判定与线上互通。代价是消息/工件版本及消费状态维护；当前尚未证明需要修改 FCoP 内核。互动议题：父任务取消后晚到的子工件，应入历史、触发重开，还是进入独立验收队列？</p><h3 id="a5-持续履职员工需要受控技能供应链与可升级运行环境" tabindex="-1">A5 持续履职员工需要受控技能供应链与可升级运行环境 <a class="header-anchor" href="#a5-持续履职员工需要受控技能供应链与可升级运行环境" aria-label="Permalink to &quot;A5 持续履职员工需要受控技能供应链与可升级运行环境&quot;">​</a></h3><p>依据：<a href="#o3">O3</a>、<a href="#o8">O8</a>、<a href="#o16">O16</a>、<a href="#o17">O17</a>、<a href="#o18">O18</a>、<a href="#o19">O19</a>、<a href="#o20">O20</a>、<a href="#o23">O23</a>、<a href="#o27">O27</a>、<a href="#o28">O28</a>、<a href="#o29">O29</a>、<a href="#o38">O38</a>、<a href="#o43">O43</a>。</p><p>已有证据支持：公共目录开关、组织来源限制、可执行脚本权限、不可变工具盘、OAuth 注册恢复和新旧状态兼容分别解决不同环节。OpenHands 默认公共来源仍开启，Copilot 的 plugin-only 还需市场限制，Orca 仓库信任涵盖未来版本，这些默认值必须写进体验方案。待验证推断：岗位/SOP 即使固定，实际 CLI、hook 或 connector 升级也会改变员工行为；需要版本与生效身份一起记录。体验候选：固定版本的 Paperclip/Orca/Paradev 作升级、重启和权限恢复对照；云盘路径依赖 Vercel，不适合作为零依赖本地交付方案直接移植。FCoP 比较工件与版本声明，安装、依赖、沙箱、凭证轮换及回滚属于 Runtime/产品交付层。代价包括旧版本兼容、缓存盘成本、操作系统权限差异和更新失败降级。互动议题：自动化信任从“已批准字节”迁移到“未来仓库内容”时，组织如何识别并撤回授权？</p><h3 id="a6-竞品与开源应用-优先体验恢复和真实交付-不按功能数量排位" tabindex="-1">A6 竞品与开源应用：优先体验恢复和真实交付，不按功能数量排位 <a class="header-anchor" href="#a6-竞品与开源应用-优先体验恢复和真实交付-不按功能数量排位" aria-label="Permalink to &quot;A6 竞品与开源应用：优先体验恢复和真实交付，不按功能数量排位&quot;">​</a></h3><p>依据：<a href="#o2">O2</a>、<a href="#o3">O3</a>、<a href="#o21">O21</a>、<a href="#o22">O22</a>、<a href="#o23">O23</a>、<a href="#o24">O24</a>、<a href="#o25">O25</a>、<a href="#o26">O26</a>、<a href="#o27">O27</a>、<a href="#o28">O28</a>、<a href="#o29">O29</a>、<a href="#o30">O30</a>、<a href="#o40">O40</a>。</p><p>已有证据支持：Paperclip 持续补任务/唤醒/停止结算，Orca 补消息来源与跨端可观测，Orkas 正式发行面向内容、商务文档的工作流，Paradev 补云环境分发与生命周期。它们分别覆盖公司任务协作、通用员工工作台、内容交付和编码环境；不能由几项 PR 推定整个企业治理已成熟。体验顺序：第一，Paperclip（MIT）验证一个父任务带多岗位、停止/恢复和独立验收；第二，Orca（MIT）验证 Agent 来信、真实人工批准、手机接管与仓库信任；第三，Orkas（MIT 源码与打包商业能力分开）验证一份可编辑文档/媒体成果跨重启恢复。Paradev（MIT）作为云分发/升级机制资料与后续体验候选。均需安装、模型/服务凭证与运行成本；本轮没有安装或付费体验。雷达判断：四者都值得继续高优先跟踪，风险分别在恢复治理、授权来源/跨端控制、业务交付广度、云运维效率；不改 Registry、不调整既定雷达圈层。</p><h2 id="跨项目共振与分类处置" tabindex="-1">跨项目共振与分类处置 <a class="header-anchor" href="#跨项目共振与分类处置" aria-label="Permalink to &quot;跨项目共振与分类处置&quot;">​</a></h2><p>来源明确的授权、停止后的结算、结果消费和可解释审计，在本轮多个项目中同时出现，支持这些具体机制值得研究；不能由此证明行业已经收敛、FCoP 存在缺陷或某个方案本地必然有效。优先实验候选是 A1、A2、A4，A3 为后续审计实验候选；A5 留存机制资料，A6 给出体验顺序。候选均未执行，不自动形成产品开发任务。公开报告仅保存技术互动议题，本轮未发送外部评论。</p><h2 id="双源核查、去重与覆盖限制" tabindex="-1">双源核查、去重与覆盖限制 <a class="header-anchor" href="#双源核查、去重与覆盖限制" aria-label="Permalink to &quot;双源核查、去重与覆盖限制&quot;">​</a></h2><ul><li><strong>GitHub 来源</strong>：以最新 Registry 的47位人物及 github-engineering 入口，加指定技术项目与两圈竞品合并为88个原始仓库入口；逐个查询 commits、Issues/PR 集合和 Releases，保存 URL、SHA、状态与核查结果，并对入选 PR 另读详情。多页补查用于恢复旧基线；满页未读完的来源保持 partial，不推进完整基线。README/安装与 License 深读集中在本轮入选应用，Discussion/Roadmap 及所有旧 Issue 评论并未穷尽。GitHub 两个链接不算两种来源。</li><li><strong>访问异常与历史缺口</strong>：TSA-AI-Workforce 三类 API 仍404，不能解释为停运或无更新。原 superset-sh/superset 返回迁移，已通过 GitHub 与官网核实 ParadevAI/Paradev，补查其近期提交；原入口历史缺口仍保留。Paperclip/Orca 历史 commits 及部分 Issue/Release 分页仍未完成；未完成分页与未核查内容单独记录，不能称全量无变化。</li><li><strong>非 GitHub 来源</strong>：实际打开 Cursor changelog、GitHub 官方 changelog 与三篇11月16日公告、MCP 官方博客，赵越、Kaptein、Agrawal、de Witt、Shaokun Zhang、Haoyu Wang 的本人/机构主页，以及 Paperclip、Orkas、Paradev 官网。Cursor 当前页最新为11月6日，MCP 博客当前页最新为11月11日，均不冒充本日新增；主页未提供可定年的新事件时不据此制造动态。Haoyu 页面链接的10月与3月论文仅留作旧线索。未完成47人全部 X 帖文、回复/线程和各公司账号的连续核查；不得解释为“社交端无新增”。</li><li><strong>人物与关系</strong>：赵越始终使用正确中文名。Kaptein 关联 Kyvvu 政策生态而非完整开源平台；de Witt 隐写仓库不等于多 Agent 安全综述官方实现；Mansura 的 bulbasaur-skill-cli 不是 AGENTSAFE 官方 Artifact。核心作者参与只按实际 PR/作者证据记录，例如 O39 的 Graham Neubig；机器人提交不能代替本人参与证明。</li><li><strong>发布与边界</strong>：本报告及英文镜像只更新当日两份 Markdown 和两个索引；现有主页入口、布局、公开快照与其他内容保留。GitHub 源文件回读、构建、gh-pages 发布、对应提交 Pages 状态和中英主页→索引→完整日报点击验收记录在本地独立回执中；网页是否已上线以该回执和聊天结果为准，本文不预先声称部署成功。未触碰 <code>research/runtime/**</code>、业务 Scheduler/Production/Publication、文章候选或评分卡。</li></ul><p><a href="./">返回每日动态</a> · <a href="./../../../en/runtime/daily-intelligence/2026-11-17">English</a></p>',205)])])}const g=e(n,[["render",p]]);export{u as __pageData,g as default};
